style.css:
@-moz-document domain("roblox.com") {
/* ? BACKGROUND (ROBLOX ONLY) */
body {
    background:
        linear-gradient(rgba(255, 230, 240, 0.85), rgba(255, 230, 240, 0.85)),
        url("https://i.ibb.co/RkMkXtjK/download-3.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    font-family: "Segoe UI", sans-serif;
}

/* ? TOP BAR */
.navbar,
.rbx-header {
    background: rgba(255, 190, 210, 0.95) !important;
    border-bottom: 2px solid #f4a7c1;
}

/* ? BUTTONS */
.btn-primary,
.btn-secondary {
    background: #f4a7c1 !important;
    border: none !important;
    border-radius: 14px;
    color: white !important;
    transition: 0.3s ease;
}

.btn-primary:hover,
.btn-secondary:hover {
    background: #f08fb2 !important;
    transform: scale(1.05);
}

/* ? CARDS / PANELS */
.section-content,
.container-main,
.card {
    background: rgba(255, 245, 250, 0.95) !important;
    border-radius: 18px;
    box-shadow: 0 8px 20px rgba(240, 143, 178, 0.25);
}

/* ? LINKS */
a {
    color: #f08fb2 !important;
}

a:hover {
    color: #d96a95 !important;
    text-decoration: none;
}

/* ? HEADINGS */
h1, h2, h3, h4 {
    color: #d96a95 !important;
}
}
